import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../Estilos/ReservasAgrupadas.css';

const ReservasAgrupadas = () => {
    const [reservas, setReservas] = useState([]);
    const [password, setPassword] = useState('');
    const [motivo, setMotivo] = useState('');
    const [showModal, setShowModal] = useState(false);
    const [selectedReserva, setSelectedReserva] = useState(null);

    useEffect(() => {
        fetchReservas();
    }, []);

    const fetchReservas = async () => {
        try {
            const response = await axios.get('http://localhost:5000/reservas-dia', {
                headers: {
                    Authorization: `Bearer ${localStorage.getItem('token')}`
                }
            });
            setReservas(response.data);
        } catch (error) {
            console.error('Error al obtener las reservas:', error);
        }
    };

    const handleDeleteClick = (reserva) => {
        setSelectedReserva(reserva);
        setShowModal(true);
    };

    const handleDeleteReserva = async () => {
        try {
            const response = await axios.delete('http://localhost:5000/admin/eliminar-reserva', {
                headers: {
                    Authorization: `Bearer ${localStorage.getItem('token')}`
                },
                data: {
                    reserva_id: selectedReserva._id,
                    password: password,
                    motivo: motivo
                }
            });
            if (response.data.message) {
                setReservas(reservas.filter(r => r._id !== selectedReserva._id));
                setShowModal(false);
            } else {
                alert(response.data.error);
            }
        } catch (error) {
            console.error('Error al eliminar la reserva:', error);
        }
    };

    return (
        <div className="reservas-agrupadas">
            <h1>Reservas Agrupadas</h1>
            <div className="reservas-contenedor">
                {['Cancha de futbol 1', 'Cancha de futbol 2', 'Cancha de futbol 3', 'Cancha de tenis 1', 'Cancha de tenis 2', 'Cancha de tenis 3'].map((cancha) => (
                    <div key={cancha} className="cancha-group">
                        <h2>{cancha}</h2>
                        {reservas
                            .filter(reserva => reserva.cancha === cancha)
                            .map((reserva) => (
                                <div className="card" key={reserva._id}>
                                    <p><strong>Equipo:</strong> {reserva.equipo}</p>
                                    <p><strong>Hora:</strong> {reserva.hora}</p>
                                    <p><strong>Email:</strong> {reserva.email_usuario}</p>
                                    <button onClick={() => handleDeleteClick(reserva)}>Eliminar Reserva</button>
                                </div>
                            ))}
                    </div>
                ))}
            </div>
            {showModal && (
                <div className="modal">
                    <div className="modal-content">
                        <h3>Confirmar Eliminación</h3>
                        <input 
                            type="password" 
                            placeholder="Contraseña" 
                            value={password} 
                            onChange={(e) => setPassword(e.target.value)} 
                        />
                        <textarea 
                            placeholder="Motivo de eliminación" 
                            value={motivo} 
                            onChange={(e) => setMotivo(e.target.value)}
                        />
                        <button onClick={handleDeleteReserva}>Confirmar</button>
                        <button onClick={() => setShowModal(false)}>Cancelar</button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ReservasAgrupadas;
